let db=null,state=null,optativesData=null,examSource=null,editingExamId=null,editingPersonalExam=false,currentGroup='A',currentWeek=37,currentSemester=1,editingId=null,filters={E:true,S:true,P:true},pdfFileName='',activeTab='MI SEMANA',browseCourseId=null,selectedWeekDate=null,courseView='calendar',selectedCourseDayIndex=(()=>{const d=new Date().getDay();return d>=1&&d<=5?d-1:0})();

const STORAGE_DB='MedCalendarDB_v4_preview';
const STORAGE_KEY='medcalendar-v4-preview';
let storageMode='indexeddb',saveQueue=Promise.resolve(),storageBlocked=false;
function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){resolve(null);return}let req;try{req=indexedDB.open(STORAGE_DB,1)}catch(e){reject(e);return}req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('app'))req.result.createObjectStore('app',{keyPath:'id'})};req.onsuccess=()=>{req.result.onversionchange=()=>req.result.close();resolve(req.result)};req.onerror=()=>reject(req.error||new Error('No se pudo abrir el almacenamiento'));req.onblocked=()=>reject(new Error('El almacenamiento está bloqueado por otra pestaña'))})}
async function dbGet(){if(!db)throw new Error('IndexedDB no está disponible');return new Promise((resolve,reject)=>{let tx;try{tx=db.transaction('app','readonly')}catch(e){reject(e);return}const r=tx.objectStore('app').get('main');let result; r.onsuccess=()=>{result=r.result?{status:'ok',value:r.result.value}:{status:'not-found',value:null}};r.onerror=()=>reject(r.error||new Error('Error al leer los datos'));tx.oncomplete=()=>resolve(result||{status:'error'});tx.onerror=()=>reject(tx.error||new Error('Error en la lectura'));tx.onabort=()=>reject(tx.error||new Error('Lectura interrumpida'))})}
async function dbPut(value){if(!db)return false;return new Promise(resolve=>{let tx;try{tx=db.transaction('app','readwrite');tx.objectStore('app').put({id:'main',value})}catch(e){resolve(false);return}tx.oncomplete=()=>resolve(true);tx.onerror=()=>resolve(false);tx.onabort=()=>resolve(false)})}
function setSaveStatus(text){const el=$('saveState');if(el)el.textContent=text}
function saveState(){if(!state||storageBlocked)return Promise.resolve(false);const snapshot=clone(state);setSaveStatus('Guardando…');saveQueue=saveQueue.then(async()=>{let ok=false;if(db){/* IndexedDB is the authoritative store when available. Do not silently fall back to localStorage after a failed write: on the next launch IndexedDB would otherwise win and hide the newer fallback copy. */ok=await dbPut(snapshot)}else{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(snapshot));storageMode='localstorage';ok=true}catch(e){ok=false}}if(ok)setSaveStatus('Guardado en este dispositivo · '+new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'}));else setSaveStatus('Error al guardar · no cierres la app y exporta una copia');return ok}).catch(()=>{setSaveStatus('Error al guardar · no cierres la app y exporta una copia');return false});return saveQueue}
function showStorageRecovery(message){storageBlocked=true;setSaveStatus('Error de lectura · datos protegidos');const panel=document.createElement('section');panel.className='storage-recovery';panel.setAttribute('role','alert');panel.innerHTML='<h2>No se han podido leer tus datos</h2><p>Por seguridad, Med USC no ha iniciado un calendario vacío ni ha sobrescrito la información existente.</p><p class="storage-recovery-detail"></p><button type="button" class="primary-btn" id="retryStorageRead">Reintentar lectura</button>';panel.querySelector('.storage-recovery-detail').textContent=message||'Comprueba el almacenamiento del navegador.';document.querySelector('main').prepend(panel);$('retryStorageRead').onclick=()=>location.reload()}
function validStoredState(value){return !!value&&typeof value==='object'&&Array.isArray(value.courses)&&value.courses.length>0&&value.courses.every(c=>c&&typeof c==='object'&&Array.isArray(c.weeks)&&c.groups&&typeof c.groups==='object')}
function preservePreMigrationCopy(value){try{const key='medusc-recovery-before-migration';const current=localStorage.getItem(key);if(!current)localStorage.setItem(key,JSON.stringify({createdAt:new Date().toISOString(),state:value}))}catch(e){console.warn('No se pudo crear copia local previa a la migración',e)}}
function makeCourse(name,startDate,weeks){const start=new Date(startDate+'T12:00:00');const meta=[];for(let i=0;i<weeks;i++){const d=new Date(start);d.setDate(d.getDate()+i*7);meta.push({number:i+1,displayNumber:i+1,semester:1,date:d.toISOString().slice(0,10),label:d.toLocaleDateString('es-ES',{day:'numeric',month:'short'})})}return{id:uid(),name,startDate,weeks:meta,subjectSettings:{},groups:{A:{subgroups:['A1','A2','A3','A4'],events:[]},B:{subgroups:['B1','B2','B3','B4'],events:[]},C:{subgroups:['C1','C2','C3','C4'],events:[]},D:{subgroups:['D1','D2','D3','D4'],events:[]}},custom:{events:[],baseGroup:null,excludedSubjects:[]}}}
function normalizeSeed(raw){const seen=new Set(),out=[];for(const e of raw){const key=[e.w,e.d,e.t,e.type,e.title,e.detail].join('|');if(seen.has(key))continue;seen.add(key);const detail=e.detail||'';let subgroup='',session='';const m=detail.match(/^(.+?)\s*·\s*(P\d+|S\d+)$/);if(m){subgroup=m[1].trim();session=m[2]}out.push({id:e.id||uid(),week:e.w,group:'B',day:e.d,start:e.t,duration:e.dur||60,type:e.type,subject:e.title,subgroup,session,room:''})}return out}
async function loadSeed(){const r=await fetch('data/medicina-2-2026-2027-grupo-B.json');return normalizeSeed(await r.json())}
async function loadOptatives(){const r=await fetch('data/optativas-2026-2027.json');if(!r.ok)throw new Error('No se pudo cargar el catálogo de optativas');optativesData=await r.json();return optativesData}
function semanticEventKey(e){let subject=String(e.subject||e.title||'').trim(),session=String(e.session||''),subgroup=String(e.subgroup||'');const typ=e.type||'E';if(!session&&typ==='E'){const m=subject.match(/^(.*?)\s+[ABCD]\s+(E\d+)$/i);if(m){subject=m[1].trim();session=m[2].toUpperCase()}}if(!session&&e.detail){const m=String(e.detail).match(/([ABCD][1-4](?:\/[ABCD][1-4])?)\s*·\s*([PS]\d+)/i);if(m){subgroup=m[1];session=m[2].toUpperCase()}}return[+(e.week??e.w??1),+(e.day??e.d??0),typ,subjectKey(subject),subgroup,session].join('|')}
function semanticEventKeyNoSubgroup(e){const parts=semanticEventKey({...e,subgroup:''}).split('|');parts.splice(4,1);return parts.join('|')}
function mergeTimetableEvents(existing,incoming){const old=[...(existing||[])],fresh=[...(incoming||[])],byKey=new Map();old.forEach((e,i)=>{const k=semanticEventKey(e);if(!byKey.has(k))byKey.set(k,[]);byKey.get(k).push(i)});const used=new Set(),merged=old.map(e=>({...e}));for(const n of fresh){const k=semanticEventKey(n),matches=byKey.get(k)||[];let idx=matches.find(i=>!used.has(i));if(idx===undefined){const fallback=old.map((e,i)=>({e,i})).filter(({e,i})=>!used.has(i)&&semanticEventKeyNoSubgroup(e)===semanticEventKeyNoSubgroup(n));if(fallback.length===1)idx=fallback[0].i}if(idx!==undefined){const prev=merged[idx];merged[idx]={...prev,...n,id:prev.id||n.id,room:prev.room||n.room||'',punctual:!!prev.punctual};used.add(idx)}else merged.push({...n})}return merged}
async function applyTimetableData(){
 // Descargar y validar todos los cursos antes de modificar el estado: evita una actualización parcial silenciosa.
 const packs={};
 for(let year=1;year<=4;year++){const response=await fetch(`data/medicina-${year}-2026-2027.json`);if(!response.ok)throw new Error(`No se pudo cargar el horario oficial de ${year}º (${response.status}). No se ha aplicado ninguna actualización.`);const pack=await response.json();if(!pack||!Array.isArray(pack.weeks)||!pack.groups||typeof pack.groups!=='object')throw new Error(`El archivo del horario de ${year}º está incompleto. No se ha aplicado ninguna actualización.`);for(const [group,events] of Object.entries(pack.groups)){if(!Array.isArray(events))throw new Error(`El grupo ${group} de ${year}º contiene datos inválidos.`)}packs[year]=pack}
 for(let year=1;year<=4;year++){const pack=packs[year];let c=state.courses.find(x=>courseYear(x)===year&&x.name==='2026-2027')||state.courses.find(x=>courseYear(x)===year);if(!c){c=makeCourse('2026-2027','2026-09-07',15);c.degreeYear=year;state.courses.push(c)}if((c.scheduleDataVersion||0)>=1)continue;c.degreeYear=year;c.name='2026-2027';c.weeks=pack.weeks.map(w=>({...w,label:new Date(w.date+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'short'})}));const groups={};for(const [g,events] of Object.entries(pack.groups)){const previous=c.groups?.[g]||{};groups[g]={subgroups:previous.subgroups?.length?previous.subgroups:(g==='OPTATIVAS'?[]:[1,2,3,4].map(n=>g+n)),events:mergeTimetableEvents(previous.events,events)}}for(const [g,value] of Object.entries(c.groups||{})){if(!['A','B','C','D'].includes(g))groups[g]=value}c.groups=groups;c.scheduleDataVersion=1;c.scheduleSource='horarios med 26-27.pdf'}
}

let onboardingStep=0,onboardingDraft={year:2,group:'B',subgroup:'',subjects:[],optatives:[],extraSubjects:[],extraOptatives:[]};
const onboardingSteps=['Configuración académica','Asignaturas de tu curso','Optativas de tu curso','Asignaturas de otros cursos','Optativas de otros cursos'];
function onboardingCourse(year){return state.courses.find(c=>courseYear(c)===+year)}
function uniqueSubjects(c,g){return [...new Set((c?.groups?.[g]?.events||[]).map(e=>e.subject).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es'))}
