function renderOnboarding(){const d=onboardingDraft,step=onboardingStep;$('onboardingProgress').textContent=`PASO ${step+1} DE 5 · ${onboardingSteps[step]}`;$('onboardingTitle').textContent=onboardingSteps[step];$('onboardingBack').classList.toggle('hidden',step===0);$('onboardingSkip').classList.toggle('hidden',step===0);$('onboardingNext').textContent=step===4?'Terminar':'Continuar';let html='';
 if(step===0){const c=onboardingCourse(d.year);html=`<div class="setup-fields"><label>Curso principal<select id="obYear">${[1,2,3,4].map(y=>`<option value="${y}" ${d.year===y?'selected':''}>${y}.º de Medicina</option>`).join('')}</select></label><label>Grupo<select id="obGroup">${(c?groupsForYear(d.year):[]).map(g=>`<option ${g===d.group?'selected':''} value="${g}">Grupo ${g}</option>`).join('')}</select></label><label>Subgrupo <span>(opcional)</span><select id="obSubgroup"><option value="">Todos los subgrupos</option>${subgroupsFor(c,d.group).map(x=>`<option value="${x}" ${d.subgroup===x?'selected':''}>${x}</option>`).join('')}</select></label></div>`}
 if(step===1){const names=uniqueSubjects(onboardingCourse(d.year),d.group);if(!d.subjects.length)d.subjects=[...names];html=`<p>Marca las asignaturas ordinarias que quieres incluir en Mi semana. Puedes cambiar esta selección después.</p><div class="onboarding-checks">${names.map(n=>`<label><input type="checkbox" data-ob-subject="${esc(n)}" ${d.subjects.includes(n)?'checked':''}><span>${esc(n)}</span></label>`).join('')}</div>`}
 if(step===2){const items=onboardingOptatives(d.year);html=`<p>Al seleccionar una optativa se añadirán automáticamente todas sus sesiones, conservando los grupos y subgrupos indicados en el documento oficial.</p><div class="onboarding-checks">${items.map(x=>`<label><input type="checkbox" data-ob-opt="${esc(x.code)}" ${d.optatives.includes(x.code)?'checked':''}><span><b>${esc(x.code)}</b><small>${x.cuatrimestre}.º cuatrimestre · ${x.events.length} sesiones en el documento</small></span></label>`).join('')||'<p>Este curso no tiene optativas en el catálogo disponible.</p>'}</div>`}
 if(step===3){const courses=state.courses.filter(c=>courseYear(c)!==+d.year);html=`<p>Opcional: añade asignaturas ordinarias de otros cursos. Se incorporarán todas las sesiones disponibles de cada asignatura.</p>${courses.map(c=>`<h3>${courseYear(c)}.º de Medicina</h3><div class="onboarding-checks">${[...new Set(Object.values(c.groups||{}).flatMap(g=>(g.events||[]).map(e=>e.subject)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es')).map(n=>`<label><input type="checkbox" data-ob-extra="${c.id}::${esc(n)}" ${d.extraSubjects.some(x=>x.courseId===c.id&&x.subject===n)?'checked':''}><span>${esc(n)}</span></label>`).join('')}</div>`).join('')}`}
 if(step===4){const courses=state.courses.filter(c=>courseYear(c)!==+d.year);html=`<p>Opcional: también puedes añadir optativas de otros cursos. Se incluirán todas las sesiones, sin elegir grupo ni subgrupo.</p>${courses.map(c=>{const items=onboardingOptatives(courseYear(c));return items.length?`<h3>${courseYear(c)}.º de Medicina</h3><div class="onboarding-checks">${items.map(x=>`<label><input type="checkbox" data-ob-extra-opt="${esc(x.code)}" ${d.extraOptatives.includes(x.code)?'checked':''}><span>${esc(x.code)}<small>${x.cuatrimestre}.º cuatrimestre</small></span></label>`).join('')}</div>`:''}).join('')||'<p>No hay optativas de otros cursos en el catálogo.</p>'}`}
 $('onboardingIntro').textContent=step===0?'Indica tu curso, grupo y subgrupo para cargar tu horario oficial.': 'Puedes dejar cualquier selección vacía y modificarla más adelante desde Mi curso → Personalizar.';$('onboardingBody').innerHTML=html;$('onboardingNext').onclick=()=>{if(step===0){d.year=+$('obYear').value;d.group=$('obGroup').value;d.subgroup=$('obSubgroup').value;if(!d.group){alert('Selecciona un grupo para continuar.');return}}if(step===1)d.subjects=[...document.querySelectorAll('[data-ob-subject]:checked')].map(x=>x.dataset.obSubject);if(step===2)d.optatives=[...document.querySelectorAll('[data-ob-opt]:checked')].map(x=>x.dataset.obOpt);if(step===3)d.extraSubjects=[...document.querySelectorAll('[data-ob-extra]:checked')].map(x=>{const [courseId,...rest]=x.dataset.obExtra.split('::');return{courseId,subject:rest.join('::')}});if(step===4)d.extraOptatives=[...document.querySelectorAll('[data-ob-extra-opt]:checked')].map(x=>x.dataset.obExtraOpt);if(step<4){onboardingStep++;renderOnboarding()}else finishOnboarding()};$('onboardingBack').onclick=()=>{if(step>0){onboardingStep--;renderOnboarding()}};$('onboardingSkip').onclick=()=>{if(step>0){onboardingStep++;renderOnboarding()}};const y=$('obYear');if(y)y.onchange=()=>{d.year=+y.value;d.group=groupsForYear(d.year)[0]||'';d.subgroup='';renderOnboarding()};const g=$('obGroup');if(g)g.onchange=()=>{d.group=g.value;d.subgroup='';renderOnboarding()};const sub=$('obSubgroup');if(sub)sub.onchange=()=>d.subgroup=sub.value;
}
function openOnboarding(){const p=state.academicProfile||{};onboardingDraft={year:p.completed?courseYear(state.courses.find(c=>c.id===p.courseId)):2,group:p.group||groupsForYear(p.completed?courseYear(state.courses.find(c=>c.id===p.courseId)):2)[0]||'A',subgroup:p.subgroup||'',subjects:[],optatives:[],extraSubjects:[],extraOptatives:[]};onboardingStep=0;renderOnboarding();$('fullOnboarding').classList.remove('hidden')}
function finishOnboarding(){const d=onboardingDraft,c=onboardingCourse(d.year),old=state.academicProfile||{},prefs=old.subjectSelectionsByCourse||{};const excluded=uniqueSubjects(c,d.group).filter(x=>!d.subjects.includes(x));prefs[c.id]={excludedSubjects:excluded};state.academicProfile={...old,completed:true,courseId:c.id,group:d.group,subgroup:d.subgroup,showOtherSubgroups:false,subjectSelectionsByCourse:prefs,excludedSubjects:excluded};state.personalPlan=state.personalPlan||{};const plan=state.personalPlan;plan.baseCourseId=c.id;plan.baseGroup=d.group;plan.selectedOptatives=[...(plan.selectedOptatives||[]),...d.optatives.filter(code=>!(plan.selectedOptatives||[]).some(x=>x.code===code)).map(code=>({code,allSessions:true}))];plan.wholeSubjects=[...(plan.wholeSubjects||[]),...d.extraSubjects.filter(x=>!(plan.wholeSubjects||[]).some(y=>y.courseId===x.courseId&&subjectKey(y.subject)===subjectKey(x.subject)))];plan.selectedExtraOptatives=[...new Set([...(plan.selectedExtraOptatives||[]),...d.extraOptatives])];state.activeCourse=c.id;state.settings.initialPersonalizationPending=false;state.settings.setupPromptDismissed=false;currentGroup=d.group;browseCourseId=c.id;$('fullOnboarding').classList.add('hidden');saveState();activeTab='MI SEMANA';renderAll();if(!tutorialFlags().introDone)setTimeout(showTutorialChoice,350)}

function arrangePersonalizeCards(){const own=$('ownCourseSubjectsMount'),other=$('otherCourseSubjectsMount');if(!own||!other)return;own.append($('excludedSubjectsPanel'),document.querySelector('.own-optatives-card'));other.append(document.querySelector('.other-regular-card'),document.querySelector('.other-optatives-card'));}
async function init(){
 arrangePersonalizeCards();
 let readResult=null,existingState=null;
 try{db=await openDB()}catch(e){db=null;console.warn('IndexedDB no disponible',e)}
 if(db){try{readResult=await dbGet();if(readResult.status==='ok')existingState=readResult.value}catch(e){console.error(e);try{const fallback=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(validStoredState(fallback)){existingState=fallback;storageMode='localstorage'}else{showStorageRecovery('La lectura de IndexedDB ha fallado y no hay una copia local válida.');return}}catch(parseError){showStorageRecovery('La lectura del almacenamiento ha fallado.');return}}}
 else {try{const fallback=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(validStoredState(fallback)){existingState=fallback;storageMode='localstorage'}else if(fallback){showStorageRecovery('La copia local existe, pero no supera la comprobación de integridad.');return}else{readResult={status:'not-found'}}}catch(e){showStorageRecovery('No se ha podido comprobar la copia local.');return}}
 if(existingState===null&&readResult?.status==='not-found'){try{const legacy=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(legacy!==null){if(!validStoredState(legacy)){showStorageRecovery('Existe una copia local anterior, pero no supera la comprobación de integridad.');return}existingState=legacy;storageMode='localstorage'}}catch(e){showStorageRecovery('No se ha podido comprobar la copia local anterior.');return}}
 if(existingState!==null){if(!validStoredState(existingState)){showStorageRecovery('Los datos encontrados no superan la comprobación básica de integridad. No se han modificado.');return}state=existingState;preservePreMigrationCopy(state)}
 else if(readResult?.status==='not-found'){
   try{const seed=await loadSeed();const base=makeCourse('2026-2027','2026-09-07',15);base.degreeYear=2;base.weeks=[...Object.entries(FIRST_SEMESTER_DATES).map(([n,date],i)=>({number:+n,displayNumber:i+1,semester:1,date,label:new Date(date+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'short'})})),...Object.entries(SECOND_SEMESTER_DATES).map(([n,date],i)=>({number:+n,displayNumber:i+1,semester:2,date,label:new Date(date+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'short'})}))];base.subjectSettings={};base.groups.B.events=seed;state={schemaVersion:3,settings:{appName:'Med USC',facultyName:'Facultade de Medicina · USC',primary:'#073575',startView:'week'},courses:[base],activeCourse:base.id,personalPlan:{baseCourseId:null,baseGroup:null,extras:[],selectedExtras:[],wholeGroups:[]}};
   }catch(e){showStorageRecovery('No se han podido cargar los datos iniciales. Recarga cuando tengas conexión.');return}
 } else {showStorageRecovery('No se ha podido determinar si existe una copia anterior.');return}
 if(state.settings){if(!state.settings.appName||state.settings.appName==='MedCalendar')state.settings.appName='Med USC';if(!state.settings.facultyName||state.settings.facultyName==='Tu calendario universitario')state.settings.facultyName='Facultade de Medicina · USC';if(!state.settings.primary||state.settings.primary==='#315b91')state.settings.primary='#073575';}
 migrateState();try{await applyTimetableData()}catch(scheduleError){console.error('No se pudieron actualizar los horarios oficiales:',scheduleError);const warning=document.createElement('section');warning.className='storage-recovery';warning.setAttribute('role','alert');warning.innerHTML='<h2>Horarios oficiales no actualizados</h2><p>Se conserva tu configuración anterior. No se ha aplicado una actualización parcial. Comprueba la conexión y vuelve a cargar la aplicación.</p>';document.querySelector('main')?.prepend(warning)}migrateState();try{await loadOptatives()}catch(e){console.warn('Catálogo de optativas no disponible',e)}try{const er=await fetch('data/examenes-2026-2027.json');if(!er.ok)throw new Error('No se pudo cargar el calendario de exámenes');examSource=await er.json();state.examsData=state.examsData||{overrides:{},personal:[]};}catch(e){console.warn('Calendario de exámenes no disponible',e)}const saved=await saveState();if(!saved){showStorageRecovery('No se ha podido verificar el guardado inicial. Tus datos en memoria no se han borrado; revisa el almacenamiento antes de continuar.');return}
 if(!selectedWeekDate)selectedWeekDate=new Date();renderAll();registerSW();updateConnection();if(!profileComplete()&&!state.settings.setupPromptDismissed)setTimeout(openOnboarding,450);else if(profileComplete()&&!tutorialFlags().introDone)setTimeout(()=>showTutorialChoice(),650);window.addEventListener('online',updateConnection);window.addEventListener('offline',updateConnection);let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(activeTab==='MI SEMANA')renderMyWeek();else renderCalendar()},120)})
}
function removeClinicalPracticeBlocks(c){const year=+(c.degreeYear||2);const subject=year===3?'PC I / P. MAT':year===4?'PC II / P. MAT':null;if(!subject)return;for(const group of Object.values(c.groups||{}))group.events=(group.events||[]).filter(e=>e.subject!==subject);if(c.custom?.events)c.custom.events=c.custom.events.filter(e=>e.subject!==subject)}
function migrateState(){state.academicProfile=state.academicProfile||{};state.academicProfile.subjectSelectionsByCourse=state.academicProfile.subjectSelectionsByCourse||{};if(state.academicProfile.completed&&state.academicProfile.courseId&&!state.academicProfile.subjectSelectionsByCourse[state.academicProfile.courseId])state.academicProfile.subjectSelectionsByCourse[state.academicProfile.courseId]={excludedSubjects:[...(state.academicProfile.excludedSubjects||[])]};state.personalPlan=state.personalPlan||{baseCourseId:null,baseGroup:null,extras:[]};state.personalPlan.extras=state.personalPlan.extras||[];for(const list of [state.personalPlan.extras,state.personalPlan.wholeSubjects||[],state.personalPlan.wholeGroups||[]])for(const item of list)if(item.subject)item.subject=subjectKey(item.subject);if(!state.academicProfile?.completed){state.personalPlan.baseCourseId=null;state.personalPlan.baseGroup=null;}else{state.personalPlan.baseCourseId=state.academicProfile.courseId;state.personalPlan.baseGroup=state.academicProfile.group;}state.personalPlan.selectedExtras=state.personalPlan.selectedExtras||[];state.personalPlan.selectedOptatives=state.personalPlan.selectedOptatives||[];state.personalPlan.wholeGroups=state.personalPlan.wholeGroups||[];browseCourseId=browseCourseId||state.activeCourse;for(const c of state.courses||[]){removeClinicalPracticeBlocks(c);c.subjectSettings=c.subjectSettings||{};for(const w of c.weeks||[]){if(!w.semester)w.semester=w.number>=37?1:2;}if(c.name==='2026-2027'){for(const [n,date] of Object.entries(SECOND_SEMESTER_DATES)){if(!c.weeks.some(w=>w.number===+n&&w.semester===2))c.weeks.push({number:+n,displayNumber:Object.keys(SECOND_SEMESTER_DATES).indexOf(n)+1,semester:2,date,label:new Date(date+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'short'})});}}for(const w of c.weeks){if(!w.displayNumber){const same=c.weeks.filter(x=>x.semester===w.semester).sort((a,b)=>new Date(a.date)-new Date(b.date));w.displayNumber=same.findIndex(x=>x.number===w.number)+1||w.number;}}for(const g of Object.values(c.groups||{})){for(const e of g.events||[])if(e.punctual===undefined)e.punctual=false}for(const e of c.custom?.events||[])if(e.punctual===undefined)e.punctual=false;}const reference=state.courses.find(c=>c.id===state.activeCourse)||state.courses[0];for(let y=1;y<=4;y++){if(!state.courses.some(c=>courseYear(c)===y)){const c=makeCourse('2026-2027',reference?.weeks?.[0]?.date||'2026-09-07',15);c.degreeYear=y;c.weeks=clone(reference?.weeks||c.weeks);state.courses.push(c)}}for(const c of state.courses){if(!c.degreeYear)c.degreeYear=2;}if(!course().weeks.some(w=>w.number===currentWeek)){currentWeek=course().weeks[0]?.number||1}currentSemester=weekMeta(currentWeek)?.semester||1;}
function profileComplete(){return !!(state?.academicProfile?.completed&&state.academicProfile.courseId&&state.academicProfile.group)}
function course(){const id=(activeTab==='MI CURSO'||activeTab==='MI SEMANA')?(profileComplete()?state.academicProfile.courseId:(browseCourseId||state.activeCourse)):(browseCourseId||state.activeCourse);return state.courses.find(c=>c.id===id)||state.courses[0]}
function courseYear(c){return +(c.degreeYear||2)}
function courseEvents(c){return Object.values(c.groups||{}).flatMap(g=>g.events||[])}
function allAvailableSubjects(c){return [...new Set(courseEvents(c).map(e=>subjectKey(e.subject)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es'))}
function planEvents(){const plan=state.personalPlan||{};const excluded=new Set((state.academicProfile?.excludedSubjects||[]).map(subjectKey));const base=plan.baseVisible===false?[]:(course().groups[plan.baseGroup||currentGroup]?.events||[]).filter(e=>!excluded.has(subjectKey(e.subject))).map(e=>({...e,_extra:false,_sourceCourse:course().id,_sourceGroup:plan.baseGroup||currentGroup}));const extras=[];for(const item of plan.extras||[]){if(item.visible===false)continue;const source=state.courses.find(c=>c.id===item.courseId);if(!source)continue;for(const [group,g] of Object.entries(source.groups||{})){for(const e of g.events||[]){if(subjectKey(e.subject)===subjectKey(item.subject))extras.push({...e,_extra:true,_sourceCourse:source.id,_sourceGroup:group});}}}return [...base,...extras]}
function eventsFor(group=currentGroup){const c=course();if(group==='OPTATIVAS'){return (optativesData?.subjects||[]).filter(x=>x.degreeYear===courseYear(c)).flatMap(subject=>(subject.events||[]).map(e=>({...e,id:e.id,subject:subject.code,group:e.rawGroupLabel||e.group,subgroup:e.subgroup||'',session:e.session||'',_optative:true,_sourceGroup:e.rawGroupLabel||e.group})));}return group==='CUSTOM'?c.custom.events:(c.groups?.[group]?.events||[])}
function weekMeta(n){return course().weeks.find(w=>w.number===n)}
function displayWeekNumber(w){const m=typeof w==='object'?w:weekMeta(w);return m?.displayNumber||m?.number||w}
function weekLabel(w){const meta=weekMeta(w);return meta?new Date(meta.date+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'long',year:'numeric'}):'Semana '+displayWeekNumber(w)}
function subjectKey(name){const raw=String(name||'').trim();const normalized=raw.replace(/\s+[ABCD]\s+E\d+$/i,'').replace(/\s+[ABCD]\s*[1-4I]\s*\/\s*[ABCD]?\s*[1-4]$/i,'').replace(/\s+[ABCD][1-4](?:\/[ABCD][1-4])?$/i,'').replace(/\s+[ABCD][1-4](?:\/[ABCD][1-4])?\s+[PS]\d+$/i,'').trim();return (normalized||raw).normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function allCourseEvents(){const c=course();return [...Object.values(c.groups||{}).flatMap(g=>g.events||[]),...(c.custom?.events||[])]}
function subjectNames(){return [...new Set(allCourseEvents().map(e=>subjectKey(e.subject)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es'))}
function subjectSettings(name){const c=course();c.subjectSettings=c.subjectSettings||{};return c.subjectSettings[subjectKey(name)]||(c.subjectSettings[subjectKey(name)]={color:'#dce8f7',room:''})}
function eventRoom(e){return e.room||subjectSettings(e.subject).room||''}
function groupLabel(g){return g==='CUSTOM'?'Horario personalizado':g==='OPTATIVAS'?'Optativas':'Grupo '+g}
function renderAll(){renderCourseSelect();renderMainTabs();renderTabs();renderAcademicProfile();const configured=profileComplete(),isWeek=activeTab==='MI SEMANA',isCourse=activeTab==='MI CURSO',isPersonalize=isCourse&&courseView==='personalize';$('weekView').classList.toggle('hidden',!isWeek);$('workspace').classList.toggle('hidden',isWeek||(isCourse&&!configured)||isPersonalize||activeTab==='EXÁMENES');$('examsView').classList.toggle('hidden',activeTab!=='EXÁMENES');$('planControls').classList.toggle('hidden',!isPersonalize||!configured);$('academicProfilePanel').classList.toggle('hidden',!isPersonalize||!configured);$('excludedSubjectsPanel').classList.toggle('hidden',!isPersonalize||!configured);$('courseSubtabs').classList.toggle('hidden',!isCourse||!configured);$('courseNotConfigured').classList.toggle('hidden',!isCourse||configured);$('courseSelect').closest('.course-picker').classList.toggle('hidden',isCourse||isWeek||activeTab==='EXÁMENES');if(configured&&isCourse){renderCourseSubtabs();renderPlanControls();renderExcludedSubjects()}if(isWeek)renderMyWeek();else if((isCourse&&configured&&!isPersonalize)||activeTab==='HORARIOS'){renderWeeks();renderFilters();renderCalendar()}if(activeTab==='EXÁMENES')renderExams();$('appName').textContent=state.settings.appName||'Med USC';$('facultyName').textContent=state.settings.facultyName||'Facultade de Medicina · USC';document.documentElement.style.setProperty('--primary',state.settings.primary||'#073575');}
function effectiveExams(){if(!examSource)return[];const data=state.examsData||{overrides:{},personal:[]};return [...examSource.exams.map(e=>({...e,...(data.overrides?.[e.id]||{}),_official:e,_status:data.overrides?.[e.id]?'modified':'official'})),...(data.personal||[]).map(e=>({...e,_status:'personal'}))]}
