function addExamSubjectKeys(target,name){const key=subjectKey(name);target.add(key);for(const alias of EXAM_SUBJECT_ALIASES[key]||[])target.add(subjectKey(alias));}
function selectedExamSubjects(){const selected=new Set(),c=course(),p=state.personalPlan||{},profile=state.academicProfile||{};const excluded=new Set(profile.excludedSubjects||[]);for(const e of c.groups?.[profile.group]?.events||[])if(![...excluded].some(x=>subjectKey(x)===subjectKey(e.subject)))addExamSubjectKeys(selected,e.subject);for(const x of p.extras||[])if(x.visible!==false&&isWholeSubjectAdded(x.courseId,x.subject))addExamSubjectKeys(selected,x.subject);for(const x of p.wholeSubjects||[])addExamSubjectKeys(selected,x.subject);for(const code of [...(p.selectedOptatives||[]).map(x=>typeof x==='string'?x:x.code),...(p.selectedExtraOptatives||[])])addExamSubjectKeys(selected,code);const ownYear=courseYear(c);if(ownYear===3)selected.add(subjectKey('Práctica Clínica I'));if(ownYear===4)selected.add(subjectKey('Práctica Clínica II'));return selected}
function examSubjectColor(e){if(e._status==='personal'&&!e.subject)return '#8b98a9';const key=subjectKey(e.subject);for(const c of state.courses){for(const [settingName,cfg] of Object.entries(c.subjectSettings||{})){const settingKey=subjectKey(settingName);if(settingKey===key||(EXAM_SUBJECT_ALIASES[settingKey]||[]).some(alias=>subjectKey(alias)===key)){if(cfg?.color)return cfg.color}}}return '#dce8f7'}
function examShortName(name){const words=String(name||'').replace(/\([^)]*\)/g,'').trim().split(/\s+/);return words.length>2?words.slice(0,2).map(x=>x.slice(0,5)).join(' '):String(name||'').slice(0,15)}
function examCategoryClass(e){return e.period==='recovery'?'recovery-exam':'final-exam'}
function renderExamMonthPicker(base){const months=[['2026-12','Diciembre','2026'],['2027-01','Enero','2027'],['2027-05','Mayo','2027'],['2027-06','Junio','2027'],['2027-07','Julio','2027']];$('examMonthPicker').innerHTML=months.map(([key,label,year])=>{const records=base.filter(e=>e.date&&e.date.startsWith(key));const hasFinal=records.some(e=>e.period==='first'||e.period==='second');const hasRecovery=records.some(e=>e.period==='recovery');return `<button type="button" data-month="${key}" class="${$('examMonthFilter').value===key?'active':''}" aria-pressed="${$('examMonthFilter').value===key?'true':'false'}"><span>${label}</span><small>${year}</small><span class="exam-month-markers" aria-label="${hasFinal?'Tiene exámenes finales':'Sin exámenes finales'}${hasRecovery?' y recuperaciones':' y sin recuperaciones'}"><i class="${hasFinal?'final-present':''}"></i><i class="${hasRecovery?'recovery-present':''}"></i></span></button>`}).join('');document.querySelectorAll('#examMonthPicker [data-month]').forEach(b=>b.onclick=()=>{$('examMonthFilter').value=b.dataset.month;renderExams()})}
function renderExams(){if(!examSource){$('examCalendar').innerHTML='<div class="empty-state">No se ha podido cargar el calendario oficial de exámenes. Tus cambios guardados no se han eliminado.</div>';return}const month=$('examMonthFilter').value,selected=selectedExamSubjects();const base=effectiveExams().filter(e=>e._status==='personal'||selected.has(subjectKey(e.subject)));renderExamMonthPicker(base);const continuous=base.filter(e=>!e.date).sort((a,b)=>a.subject.localeCompare(b.subject,'es'));const items=base.filter(e=>e.date&&e.date.startsWith(month)).sort((a,b)=>a.date.localeCompare(b.date)||a.subject.localeCompare(b.subject,'es'));const monthStart=new Date(month+'-01T12:00:00'),days=new Date(monthStart.getFullYear(),monthStart.getMonth()+1,0).getDate(),offset=(monthStart.getDay()+6)%7;let html='<div class="exam-month-grid">'+['L','M','X','J','V','S','D'].map(x=>`<div class="exam-day-head">${x}</div>`).join('');for(let i=0;i<offset;i++)html+='<div class="exam-day empty"></div>';for(let d=1;d<=days;d++){const iso=month+'-'+String(d).padStart(2,'0'),dayItems=items.filter(e=>e.date===iso);html+=`<div class="exam-day"><strong>${d}</strong>${dayItems.map(e=>`<button type="button" class="exam-chip ${e._status} ${examCategoryClass(e)}" data-exam-id="${esc(e.id)}" data-personal="${e._status==='personal'?'1':'0'}"><span>${esc(examShortName(e.subject))}</span><small>${esc(e.time||'Sin hora')}</small></button>`).join('')}</div>`}html+='</div><div class="exam-list"><h2>Exámenes del mes</h2>';if(!items.length)html+='<p class="empty-state">No hay exámenes de las asignaturas seleccionadas en este mes.</p>';for(const e of items){const date=new Date(e.date+'T12:00:00').toLocaleDateString('es-ES',{weekday:'short',day:'numeric',month:'long'}),label=e.period==='first'?'Primer cuatrimestre':e.period==='second'?'Segundo cuatrimestre':'Segunda oportunidad';html+=`<button type="button" class="exam-row ${e._status} ${examCategoryClass(e)}" data-exam-id="${esc(e.id)}" data-personal="${e._status==='personal'?'1':'0'}"><span class="exam-date">${esc(date)}</span><span class="exam-info"><strong>${esc(e.subject)}</strong><small>${e.course}.º · ${label} · ${esc(e.time||'Sin hora')}${e.rooms?' · Aulas '+esc(e.rooms):''}${e.notes?' · '+esc(e.notes):''}</small></span><span class="exam-state">${e._status==='modified'?'Modificado':e._status==='personal'?'Personal':'Oficial'}</span></button>`}html+='</div>';if(continuous.length){html+='<div class="exam-list continuous-list"><h2>Evaluación continua · sin fecha fija</h2>';for(const e of continuous)html+=`<button type="button" class="exam-row continuous ${examCategoryClass(e)}" data-exam-id="${esc(e.id)}" data-personal="${e._status==='personal'?'1':'0'}"><span class="exam-date">Sin fecha</span><span class="exam-info"><strong>${esc(e.subject)}</strong><small>${e.course}.º · ${e.period==='second'?'Segundo cuatrimestre':'Segunda oportunidad'} · Evaluación continua</small></span><span class="exam-state">Continua</span></button>`;html+='</div>'}$('examCalendar').innerHTML=html;document.querySelectorAll('[data-exam-id]').forEach(b=>b.onclick=()=>openExamEditor(b.dataset.examId,b.dataset.personal==='1'));document.querySelectorAll('[data-month]').forEach(b=>b.classList.toggle('active',b.dataset.month===month));}

function openExamEditor(id,personal=false){editingExamId=id;editingPersonalExam=personal;const e=effectiveExams().find(x=>x.id===id);if(!e)return;$('examModalTitle').textContent=personal?'Editar examen personal':'Editar examen oficial';$('examSubject').value=e.subject;$('examCourse').value=String(e.course);$('examPeriod').value=e.period;$('examDate').value=e.date||'';$('examTime').value=e.time||'';$('examRooms').value=e.rooms||'';$('examNotes').value=e.notes||'';$('deletePersonalExam').classList.toggle('hidden',!personal);$('restoreOfficialExam').classList.toggle('hidden',personal||!state.examsData?.overrides?.[id]);$('examEditHint').textContent=personal?'Este examen es personal. Puedes modificarlo o eliminarlo.':'Los datos oficiales originales se conservan y puedes restaurarlos. Las notas personales se mantienen al restaurar.';$('examModal').classList.remove('hidden')}
function closeExamEditor(){$('examModal').classList.add('hidden');editingExamId=null}
function saveExamEditor(){const subject=$('examSubject').value.trim();if(!subject){alert('Indica la asignatura.');return}const date=$('examDate').value||null,time=$('examTime').value||null;if((date&&!/^202[6-7]-/.test(date))){alert('La fecha debe pertenecer al curso 2026–2027.');return}state.examsData=state.examsData||{overrides:{},personal:[]};const patch={subject,course:+$('examCourse').value,period:$('examPeriod').value,date,time,rooms:$('examRooms').value.trim(),notes:$('examNotes').value.trim()};if(editingPersonalExam){const i=state.examsData.personal.findIndex(x=>x.id===editingExamId);if(i>=0)state.examsData.personal[i]={...state.examsData.personal[i],...patch};}else{const original=examSource.exams.find(x=>x.id===editingExamId);if(!original)return;state.examsData.overrides[editingExamId]={...patch,kind:original.kind,originalPeriod:original.originalPeriod,sourcePage:original.sourcePage};}saveState();closeExamEditor();renderExams()}
function addPersonalExam(){state.examsData=state.examsData||{overrides:{},personal:[]};const id='personal-'+Date.now().toString(36);state.examsData.personal.push({id,course:profileComplete()?courseYear(course()):2,subject:'',date:$('examMonthFilter').value+'-01',time:'',rooms:'',period:'first',kind:'personal',notes:''});openExamEditor(id,true)}
function deletePersonalExam(){if(!editingPersonalExam||!confirm('¿Eliminar este examen personal?'))return;state.examsData.personal=state.examsData.personal.filter(x=>x.id!==editingExamId);saveState();closeExamEditor();renderExams()}
function restoreOfficialExam(){if(!editingExamId)return;const notes=state.examsData?.overrides?.[editingExamId]?.notes||'';delete state.examsData.overrides[editingExamId];if(notes)state.examsData.overrides[editingExamId]={notes};saveState();closeExamEditor();renderExams()}
function renderCourseSubtabs(){document.querySelectorAll('[data-course-view]').forEach(b=>{b.classList.toggle('active',b.dataset.courseView===courseView);b.onclick=()=>{courseView=b.dataset.courseView;renderAll()}})}
function renderExcludedSubjects(){const c=course(),profile=state.academicProfile,byCourse=profile.subjectSelectionsByCourse||(profile.subjectSelectionsByCourse={}),prefs=byCourse[c.id]||(byCourse[c.id]={excludedSubjects:[...(profile.excludedSubjects||[])]}),names=[...new Set((c.groups[profile.group]?.events||[]).map(e=>subjectKey(e.subject)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es')),excluded=new Set(prefs.excludedSubjects||[]);profile.excludedSubjects=[...(prefs.excludedSubjects||[])];$('excludedSubjectsList').innerHTML=names.map(n=>`<label class=\"excluded-subject-item\"><input type=\"checkbox\" data-subject-visible=\"${esc(n)}\" ${excluded.has(n)?'':'checked'}><span>${esc(n)}</span></label>`).join('');document.querySelectorAll('[data-subject-visible]').forEach(el=>el.onchange=()=>{const name=el.dataset.subjectVisible;prefs.excludedSubjects=prefs.excludedSubjects||[];if(el.checked)prefs.excludedSubjects=prefs.excludedSubjects.filter(x=>subjectKey(x)!==subjectKey(name));else if(!prefs.excludedSubjects.some(x=>subjectKey(x)===subjectKey(name)))prefs.excludedSubjects.push(name);profile.excludedSubjects=[...prefs.excludedSubjects];saveState();renderCalendar();renderMyWeek()})}
function renderCourseSelect(){const selected=(browseCourseId||state.activeCourse);$('courseSelect').innerHTML=[...state.courses].sort((a,b)=>courseYear(a)-courseYear(b)).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${courseYear(c)}.º Medicina</option>`).join('')}
function activateMainTab(tab){activeTab=tab;if(tab==='MI CURSO'){courseView='calendar'}if(tab==='MI CURSO'||tab==='MI SEMANA'){currentGroup=profileComplete()?state.academicProfile.group:'A'}else{currentGroup='A'}if(tab==='MI SEMANA'&&!selectedWeekDate)selectedWeekDate=new Date();currentWeek=course().weeks[0]?.number||37;currentSemester=weekMeta(currentWeek)?.semester||1;renderAll();setTimeout(()=>maybeStartTabTutorial(activeTab),260)}
function renderMainTabs(){document.querySelectorAll('[data-main-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.mainTab===activeTab);b.setAttribute('aria-current',b.dataset.mainTab===activeTab?'page':'false');b.onclick=()=>activateMainTab(b.dataset.mainTab)});$('groupTabs').classList.toggle('hidden',activeTab!=='HORARIOS')}
function renderTabs(){const groups=Object.keys(course().groups).filter(g=>['A','B','C','D','OPTATIVAS'].includes(g));if((optativesData?.subjects||[]).some(x=>x.degreeYear===courseYear(course()))&&!groups.includes('OPTATIVAS'))groups.push('OPTATIVAS');if(!groups.includes(currentGroup))currentGroup=groups[0]||'A';$('groupTabs').innerHTML=groups.map(g=>`<button class="group-tab ${g===currentGroup?'active':''}" data-group="${esc(g)}">${g==='OPTATIVAS'?'Optativas':'Grupo '+esc(g)}</button>`).join('');document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{currentGroup=b.dataset.group;if(currentGroup==='OPTATIVAS'){const optEvents=eventsFor('OPTATIVAS');let semesterEvents=optEvents.filter(e=>weekMeta(e.week)?.semester===currentSemester);if(!semesterEvents.length){semesterEvents=optEvents.filter(e=>weekMeta(e.week));}if(semesterEvents.length&&!semesterEvents.some(e=>e.week===currentWeek)){const first=semesterEvents.sort((a,b)=>a.week-b.week||a.start-b.start)[0];currentWeek=first.week;currentSemester=weekMeta(first.week)?.semester||currentSemester;}}if(activeTab==='MI CURSO'&&profileComplete()){state.academicProfile.group=currentGroup;state.personalPlan.baseGroup=currentGroup;saveState();renderAcademicProfile();}renderTabs();renderWeeks();renderFilters();renderCalendar()})}
function renderAcademicProfile(){const p=state.academicProfile;if(profileComplete()){$('academicProfileSummary').textContent=`${courseYear(state.courses.find(c=>c.id===p.courseId))}.º de Medicina · Grupo ${p.group} · ${p.subgroup||'Todos los subgrupos'}`;}$('configureCourseBtn').onclick=()=>openAcademicSetup(false);$('editAcademicProfileBtn').onclick=()=>openAcademicSetup(false)}
function groupsForYear(year){const c=state.courses.find(x=>courseYear(x)===+year);return c?Object.keys(c.groups||{}).filter(g=>['A','B','C','D'].includes(g)):[]}
function subgroupsFor(c,g){const values=new Set(c?.groups?.[g]?.subgroups||[]);for(const e of c?.groups?.[g]?.events||[]){for(const m of String(e.subgroup||'').matchAll(/[A-D][1-4]/g))values.add(m[0])}return [...values].filter(x=>new RegExp('^'+g+'[1-4]$').test(x)).sort()}
