function fillAcademicSetup(){const year=$('academicYearSelect').value,groups=groupsForYear(year),g=$('academicGroupSelect').value;const groupSelect=$('academicGroupSelect');groupSelect.innerHTML='<option value="">Selecciona tu grupo</option>'+groups.map(x=>`<option value="${x}">Grupo ${x}</option>`).join('');if(groups.includes(g))groupSelect.value=g;const subs=subgroupsFor(state.courses.find(c=>courseYear(c)===+year),groupSelect.value);const old=$('academicSubgroupSelect').value;$('academicSubgroupSelect').innerHTML='<option value="">Todos los subgrupos</option>'+subs.map(x=>`<option value="${x}">${x}</option>`).join('');if(subs.includes(old))$('academicSubgroupSelect').value=old;$('academicGroupSelect').disabled=!year;$('academicSubgroupSelect').disabled=!groupSelect.value;$('saveAcademicProfile').disabled=!(year&&groupSelect.value)}
function openAcademicSetup(initial=false){setupInitial=initial;const profile=state.academicProfile||{};$('academicSetupTitle').textContent=initial?'¡Vamos a configurar tu horario!':'Cambia tu configuración académica';$('academicYearSelect').innerHTML='<option value="">Selecciona tu curso</option>'+[1,2,3,4].map(y=>`<option value="${y}">${y}.º de Medicina</option>`).join('');$('academicYearSelect').value=profile.completed?String(courseYear(state.courses.find(c=>c.id===profile.courseId))):'';$('academicGroupSelect').innerHTML='<option value="">Selecciona tu grupo</option>';$('academicGroupSelect').value='';$('academicSubgroupSelect').innerHTML='<option value="">Todos los subgrupos</option>';$('academicSubgroupSelect').value='';if(profile.completed){$('academicGroupSelect').innerHTML='<option value="">Selecciona tu grupo</option>'+groupsForYear($('academicYearSelect').value).map(g=>`<option value="${g}">Grupo ${g}</option>`).join('');$('academicGroupSelect').value=profile.group||'';const subs=subgroupsFor(state.courses.find(c=>courseYear(c)===+$('academicYearSelect').value),profile.group);$('academicSubgroupSelect').innerHTML='<option value="">Todos los subgrupos</option>'+subs.map(x=>`<option value="${x}">${x}</option>`).join('');$('academicSubgroupSelect').value=profile.subgroup||'';}$('setupCancel').classList.toggle('hidden',initial);$('setupBrowseSchedules').classList.toggle('hidden',!initial);$('academicSetup').classList.remove('hidden');fillAcademicSetup()}
$('academicYearSelect').onchange=()=>{ $('academicGroupSelect').value='';$('academicSubgroupSelect').value='';fillAcademicSetup()};$('academicGroupSelect').onchange=()=>{$('academicSubgroupSelect').value='';fillAcademicSetup()};$('saveAcademicProfile').onclick=()=>{const year=+$('academicYearSelect').value,group=$('academicGroupSelect').value,subgroup=$('academicSubgroupSelect').value,c=state.courses.find(x=>courseYear(x)===year);if(!c||!group){alert('Selecciona tu curso y tu grupo.');return}const wasConfigured=profileComplete(),oldProfile=state.academicProfile||{},preferences=oldProfile.subjectSelectionsByCourse||{};if(oldProfile.completed&&oldProfile.courseId&&!preferences[oldProfile.courseId])preferences[oldProfile.courseId]={excludedSubjects:[...(oldProfile.excludedSubjects||[])]};const selectedPrefs=preferences[c.id]||{excludedSubjects:[]};preferences[c.id]=selectedPrefs;state.academicProfile={...oldProfile,completed:true,courseId:c.id,group,subgroup,showOtherSubgroups:false,subjectSelectionsByCourse:preferences,excludedSubjects:[...(selectedPrefs.excludedSubjects||[])]};state.personalPlan=state.personalPlan||{extras:[],selectedExtras:[],wholeGroups:[]};/* Al cambiar el curso principal se conservan las asignaturas adicionales de otros cursos. */state.personalPlan.baseCourseId=c.id;state.personalPlan.baseGroup=group;state.activeCourse=c.id;browseCourseId=c.id;currentGroup=group;currentWeek=c.weeks[0]?.number||37;currentSemester=weekMeta(currentWeek)?.semester||1;selectedWeekDate=selectedWeekDate||new Date();state.settings.setupPromptDismissed=false;if(!wasConfigured&&setupInitial)state.settings.initialPersonalizationPending=true;saveState();$('academicSetup').classList.add('hidden');if(!wasConfigured&&setupInitial){activeTab='MI CURSO';courseView='personalize';}renderAll();if(!wasConfigured&&setupInitial){$('initialPersonalizationNotice').classList.remove('hidden');}else if(!tutorialFlags().introDone)setTimeout(showTutorialChoice,350)};
$('setupBrowseSchedules').onclick=()=>{state.settings.setupPromptDismissed=true;saveState();$('academicSetup').classList.add('hidden');activeTab='HORARIOS';browseCourseId=state.activeCourse;currentGroup='A';renderAll()};$('setupCancel').onclick=()=>{$('academicSetup').classList.add('hidden')};
