 $('baseCourseVisibilityMount').innerHTML=`<label class="extra-filter base-course-filter"><input type="checkbox" data-base-visible ${plan.baseVisible!==false?'checked':''}><span>Mostrar las clases ordinarias de tu curso principal</span><small>${courseYear(course())}.º · ${esc(plan.baseGroup||'')}</small></label>`;
 $('extraSubjectFilters').innerHTML=plan.extras.map((x,i)=>{const c=state.courses.find(z=>z.id===x.courseId),added=isWholeSubjectAdded(x.courseId,x.subject);return `<div class="extra-subject-row"><label class="extra-filter"><input type="checkbox" data-extra-index="${i}" ${x.visible!==false?'checked':''}><span>${esc(x.subject)}</span><small>${c?courseYear(c)+'.º':''} · Todos los grupos</small></label><button type="button" class="small-btn" data-toggle-whole-subject="${i}">${added?'Quitar de Mi semana':'Añadir todas a Mi semana'}</button><button type="button" class="remove-extra" data-remove-extra="${i}" aria-label="Quitar ${esc(x.subject)}">×</button></div>`}).join('')||'<p class="empty-selection">No has añadido asignaturas ordinarias de otros cursos.</p>';
 const baseToggle=document.querySelector('#baseCourseVisibilityMount [data-base-visible]');if(baseToggle)baseToggle.onchange=()=>{plan.baseVisible=baseToggle.checked;saveState();renderCalendar();renderMyWeek()};
 document.querySelectorAll('[data-extra-index]').forEach(el=>el.onchange=()=>{plan.extras[+el.dataset.extraIndex].visible=el.checked;saveState();renderCalendar()});
 document.querySelectorAll('[data-remove-extra]').forEach(el=>el.onclick=()=>{const item=plan.extras[+el.dataset.removeExtra];plan.extras.splice(+el.dataset.removeExtra,1);plan.wholeSubjects=plan.wholeSubjects.filter(x=>!(x.courseId===item.courseId&&subjectKey(x.subject)===subjectKey(item.subject)));plan.wholeGroups=plan.wholeGroups.filter(x=>!(x.courseId===item.courseId&&subjectKey(x.subject)===subjectKey(item.subject)));plan.selectedExtras=plan.selectedExtras.filter(x=>x.courseId!==item.courseId);saveState();renderPlanControls();renderCalendar();renderMyWeek()});
 document.querySelectorAll('[data-toggle-whole-subject]').forEach(el=>el.onclick=()=>{const item=plan.extras[+el.dataset.toggleWholeSubject];if(isWholeSubjectAdded(item.courseId,item.subject)){plan.wholeSubjects=plan.wholeSubjects.filter(x=>!(x.courseId===item.courseId&&subjectKey(x.subject)===subjectKey(item.subject)));plan.wholeGroups=plan.wholeGroups.filter(x=>!(x.courseId===item.courseId&&subjectKey(x.subject)===subjectKey(item.subject)));plan.selectedExtras=plan.selectedExtras.filter(x=>x.courseId!==item.courseId);saveState();renderPlanControls();renderMyWeek();return}addWholeSubjectToWeek(item.courseId,item.subject)});
 const missing=plan.extras.filter(x=>!state.courses.find(c=>c.id===x.courseId)||!courseEvents(state.courses.find(c=>c.id===x.courseId)).length);$('planDataNotice').textContent=missing.length?'Las asignaturas seleccionadas aún no tienen datos de horario cargados.':'';
 plan.selectedOptatives=plan.selectedOptatives||[];
