 plan.selectedOptatives=normalizeOptatives(plan.selectedOptatives);
 plan.selectedExtraOptatives=[...new Set((plan.selectedExtraOptatives||[]).map(x=>typeof x==='string'?x:x.code).filter(Boolean))];
 const allOptatives=optativesData?.subjects||[],year=courseYear(course());
 if(optativesData?.subjects){const selectedCodes=[...new Set([...(plan.selectedOptatives||[]).map(x=>typeof x==='string'?x:x.code),...(plan.selectedExtraOptatives||[])].filter(Boolean))];const nextOwn=selectedCodes.filter(code=>allOptatives.some(item=>item.code===code&&item.degreeYear===year)).map(code=>({code,allSessions:true}));const nextOther=selectedCodes.filter(code=>allOptatives.some(item=>item.code===code&&item.degreeYear!==year));const changed=JSON.stringify(plan.selectedOptatives)!==JSON.stringify(nextOwn)||JSON.stringify(plan.selectedExtraOptatives)!==JSON.stringify(nextOther);plan.selectedOptatives=nextOwn;plan.selectedExtraOptatives=nextOther;if(changed)saveState();}
 $('optativesSourceNotice').textContent=optativesData?'Fuente: Horarios optativas hasta 4to de carrera.pdf. Se incorporan todas las sesiones y se conservan sus etiquetas oficiales.':'No se ha podido cargar el catálogo de optativas.';
 const own=allOptatives.filter(x=>x.degreeYear===year);
 $('optativeSelect').innerHTML='<option value="">Optativa</option>'+own.map(x=>`<option value="${esc(x.code)}">${esc(x.code)} · ${x.cuatrimestre}.º cuatrimestre · ${x.events.length} sesiones</option>`).join('');
 $('addOptativeBtn').onclick=()=>{const code=$('optativeSelect').value;if(!code)return alert('Selecciona una optativa.');if(plan.selectedOptatives.some(x=>x.code===code))return alert('Esa optativa ya está añadida.');plan.selectedOptatives.push({code,allSessions:true});saveState();renderPlanControls();renderMyWeek()};
