function saveOneOffRoom(){const n=$('subjectSelect').value,index=+$('roomOverrideSession').value;if(!n||!Number.isInteger(index))return;const e=allCourseEvents()[index];if(!e||subjectKey(e.subject)!==subjectKey(n)){alert('No se ha podido identificar la sesión. Vuelve a seleccionarla.');return}const room=$('roomOverrideValue').value.trim();if(!room){alert('Escribe el aula puntual que quieres asignar.');return}e.room=room;e.punctual=true;saveState();loadSubjectEditor();renderCalendar();renderMyWeek()}function clearOneOffRoom(){const n=$('subjectSelect').value,index=+$('roomOverrideSession').value;if(!n||!Number.isInteger(index))return;const e=allCourseEvents()[index];if(!e||subjectKey(e.subject)!==subjectKey(n))return;e.room='';e.punctual=false;saveState();loadSubjectEditor();renderCalendar();renderMyWeek()}
function settingsOpen(){const s=state.settings;$('settingAppName').value=s.appName||'Med USC';$('settingFaculty').value=s.facultyName||'';$('settingColor').value=s.primary||'#073575';$('settingStartView').value=s.startView||'week';const g=['A','B','C','D'].includes(currentGroup)?currentGroup:(state.academicProfile?.group||'B');show('settingsModal')}
