async function resetCalendar(){if(!confirm('Se restaurarán los datos oficiales del horario del curso activo. Se conservarán las asignaturas adicionales, optativas seleccionadas, preferencias personales, cambios puntuales de aula y exámenes. ¿Continuar?'))return;try{const c=course(),year=courseYear(c),response=await fetch(`data/medicina-${year}-2026-2027.json`);if(!response.ok)throw new Error('No se pudo recuperar el horario oficial');const pack=await response.json();const roomOverrides=new Map();for(const [group,g] of Object.entries(c.groups||{}))for(const e of g.events||[])if(e.punctual&&e.room){const key=semanticEventKey(e);if(!roomOverrides.has(key))roomOverrides.set(key,[]);roomOverrides.get(key).push({group,room:e.room})}const nextGroups={};for(const [g,events] of Object.entries(pack.groups)){const previous=c.groups?.[g]||{};nextGroups[g]={subgroups:previous.subgroups?.length?previous.subgroups:(g==='OPTATIVAS'?[]:[1,2,3,4].map(n=>g+n)),events:events.map(e=>{const restored={...e};const match=(roomOverrides.get(semanticEventKey(e))||[]).find(x=>x.group===g);if(match){restored.room=match.room;restored.punctual=true}return restored})}}for(const [g,value] of Object.entries(c.groups||{}))if(!Object.prototype.hasOwnProperty.call(nextGroups,g)&&!['A','B','C','D','OPTATIVAS'].includes(g))nextGroups[g]=value;c.groups=nextGroups;c.weeks=pack.weeks.map(w=>({...w,label:new Date(w.date+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'short'})}));/* Preserve independent personal settings, extras, optatives, exam data, subgroup definitions and one-off room overrides. */c.scheduleDataVersion=1;c.scheduleSource='horarios med 26-27.pdf';currentGroup=state.academicProfile?.group||'B';currentWeek=c.weeks[0]?.number||37;currentSemester=1;const saved=await saveState();if(!saved)throw new Error('No se pudo verificar el guardado. No se ha confirmado la restauración.');hide('settingsModal');renderAll()}catch(error){alert('No se pudo restablecer el horario: '+error.message)}}
