const INTRO_STEPS=[
 {selector:'.main-tabs [data-main-tab="MI SEMANA"]',title:'Mi semana',text:'Aquí aparece tu horario personal según el curso, grupo y subgrupo que configuraste. Las asignaturas de otros cursos que añadas se distinguen con borde discontinuo.'},
 {selector:'.main-tabs [data-main-tab="MI CURSO"]',title:'Mi curso',text:'Aquí puedes cambiar tu curso principal, grupo y subgrupo, seleccionar asignaturas y optativas y añadir asignaturas de otros cursos.'},
 {selector:'.main-tabs [data-main-tab="HORARIOS"]',title:'Horarios',text:'Aquí puedes consultar los horarios generales de Medicina por curso, grupo, subgrupo y tipo de clase. Consultar un horario no lo añade automáticamente a Mi semana.'},
 {selector:'.main-tabs [data-main-tab="EXÁMENES"]',title:'Exámenes',text:'Aquí puedes consultar las convocatorias oficiales, editar sus datos sin perder el original y añadir tus propios exámenes.'}
];
const TAB_STEPS={
 'MI SEMANA':[
  {selector:'#weekView',title:'Tu horario personal',text:'Aquí aparecen las clases de tu curso y grupo, filtradas por el subgrupo que hayas elegido, junto con las asignaturas adicionales que incorpores.'},
  {selector:'#weekView',title:'Otros subgrupos',text:'Si has elegido un subgrupo concreto, desde esta vista puedes mostrar temporalmente también las prácticas y sesiones de los demás subgrupos de tu grupo.'},
  {selector:'#weekView .week-view-controls',title:'Muévete por el calendario',text:'Usa las flechas para cambiar de semana (o de día en el móvil). El botón «Hoy» vuelve a la fecha actual.'}
 ],
 'MI CURSO':[
  {selector:'#academicProfilePanel',title:'Tu configuración académica',text:'Aquí puedes revisar o cambiar tu curso principal, grupo y subgrupo. Esta selección determina qué clases aparecen en Mi semana.'},
  {selector:'#planControls',title:'Añade asignaturas',text:'Selecciona el curso y la asignatura que quieras incorporar para comparar sus clases con tu grupo principal.'},
  {selector:'#extraSubjectFilters',title:'Filtra lo que estás comparando',text:'Activa o desactiva el curso principal y cada asignatura por separado. Cada asignatura adicional muestra las clases de todos sus grupos (A, B, C y D).'},
  {selector:'#calendar',title:'Elige qué añadir a Mi semana',text:'Puedes añadir de una vez todas las clases de esa asignatura, de todos los grupos y subgrupos. Si coinciden con otras clases, Med USC te avisará antes de continuar.'}
 ],
 'HORARIOS':[
  {selector:'#courseSelect',title:'Empieza por el curso',text:'Selecciona primero el curso de Medicina cuyo horario quieres consultar.'},
  {selector:'#groupTabs',title:'Escoge el grupo',text:'Después selecciona el grupo A, B, C o D. Las opciones disponibles dependen del curso.'},
  {selector:'#subgroupFilter',title:'Afina la consulta',text:'Puedes limitar la vista a un subgrupo concreto o mantener «Todos los subgrupos».'},
  {selector:'#typeFilters',title:'Filtra por tipo de clase',text:'Activa o desactiva expositivas (E), seminarios (S) y prácticas (P) para ver solo lo que necesitas.'},
  {selector:'#calendar',title:'Consulta las semanas',text:'Cambia de semana y cuatrimestre para recorrer el horario. Esta pestaña es de consulta: para configurar tu horario personal, utiliza Mi curso.'}
 ]
};
function showTutorialChoice(){$('tutorialChoice').classList.remove('hidden')}
function chooseTutorial(seeIt){const flags=tutorialFlags();$('tutorialChoice').classList.add('hidden');if(seeIt){startTutorial('intro');return}flags.introDone=true;flags.introSkipped=true;for(const tab of Object.keys(TAB_STEPS))flags[tab]=true;saveTutorialFlags(flags)}
$('tutorialChooseYes').onclick=()=>chooseTutorial(true);$('tutorialChooseNo').onclick=()=>chooseTutorial(false);
function startTutorial(mode){tutorialMode=mode;tutorialSteps=mode==='intro'?INTRO_STEPS:(TAB_STEPS[mode]||TAB_STEPS[activeTab]);if(mode==='intro'&&window.matchMedia('(max-width: 700px)').matches){const tabs=['MI SEMANA','MI CURSO','HORARIOS','EXÁMENES'];tutorialSteps=tutorialSteps.map((step,i)=>({...step,selector:`.bottom-nav [data-main-tab=\"${tabs[i]}\"]`}))}tutorialIndex=0;if($('helpMenu'))$('helpMenu').open=false;$('tutorialLayer').classList.remove('hidden');document.body.classList.add('tutorial-open');showTutorialStep()}
function showTutorialStep(){const step=tutorialSteps[tutorialIndex];if(!step)return;const target=document.querySelector(step.selector);$('tutorialKicker').textContent=tutorialMode==='intro'?'PRIMEROS PASOS':`AYUDA · ${tutorialMode}`;$('tutorialTitle').textContent=step.title;$('tutorialText').textContent=step.text;$('tutorialProgress').innerHTML=tutorialSteps.map((_,i)=>`<span class="${i<=tutorialIndex?'active':''}"></span>`).join('');$('tutorialPrev').disabled=tutorialIndex===0;$('tutorialPrev').style.opacity=tutorialIndex===0?'.45':'1';$('tutorialNext').textContent=tutorialIndex===tutorialSteps.length-1?'Terminar':'Siguiente';
 const spot=$('tutorialSpotlight');if(target){target.scrollIntoView({behavior:'smooth',block:'nearest',inline:'nearest'});requestAnimationFrame(()=>{const r=target.getBoundingClientRect(),pad=7;spot.style.display='block';spot.style.left=(r.left-pad)+'px';spot.style.top=(r.top-pad)+'px';spot.style.width=(r.width+pad*2)+'px';spot.style.height=(r.height+pad*2)+'px';});}else{spot.style.display='none'}
}
function closeTutorial(skipped=false){const flags=tutorialFlags();if(tutorialMode==='intro'){flags.introDone=true;if(skipped)flags.introSkipped=true;saveTutorialFlags(flags);$('tutorialLayer').classList.add('hidden');document.body.classList.remove('tutorial-open');const tab=activeTab;if(!flags[tab])setTimeout(()=>startTutorial(tab),220);tutorialMode=null;}
 else{flags[tutorialMode]=true;if(skipped)flags[tutorialMode+'Skipped']=true;saveTutorialFlags(flags);$('tutorialLayer').classList.add('hidden');document.body.classList.remove('tutorial-open');tutorialMode=null;}}
function maybeStartTabTutorial(tab){const flags=tutorialFlags();if(flags.introDone&&!flags[tab]&&!$('tutorialLayer').classList.contains('hidden'))return;if(flags.introDone&&!flags[tab])startTutorial(tab)}
function tutorialNext(){if(tutorialIndex<tutorialSteps.length-1){tutorialIndex++;showTutorialStep()}else closeTutorial(false)}
function tutorialPrev(){if(tutorialIndex>0){tutorialIndex--;showTutorialStep()}}
$('tutorialNext').onclick=tutorialNext;$('tutorialPrev').onclick=tutorialPrev;$('tutorialSkip').onclick=$('tutorialSkipTop').onclick=()=>closeTutorial(true);
$('restartGeneralHelp').onclick=()=>startTutorial('intro');$('restartSectionHelp').onclick=()=>startTutorial(activeTab);
window.addEventListener('resize',()=>{if(!$('tutorialLayer').classList.contains('hidden'))showTutorialStep()});

$('examMonthFilter').onchange=renderExams;$('addPersonalExam').onclick=addPersonalExam;$('closeExamModal').onclick=$('cancelExamModal').onclick=closeExamEditor;$('saveExamModal').onclick=saveExamEditor;$('deletePersonalExam').onclick=deletePersonalExam;$('restoreOfficialExam').onclick=restoreOfficialExam;

init();
